DROP TABLE IF EXISTS `bb_notifications`.`notification_tracker`;
CREATE TABLE `bb_notifications`.`notification_tracker` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `handle_type` varchar(255),
  `handle_value` varchar(255),
