  `subject` varchar(500),
  `sent_on` timestamp,
  `status` varchar(255),
  `code` varchar(255),
  `sender_code` varchar(255),
  `retry_count` int,
  `stan` varchar(255),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bb_notifications`.`sequences`;
CREATE TABLE `bb_notifications`.`sequences` (
  `sequence_name` varchar(64) NOT NULL,
  `prefix` varchar(64),
  `len` int unsigned NOT NULL DEFAULT 10,
  `pad_char` char(1) NOT NULL DEFAULT '0',
  `increment_by` int unsigned NOT NULL DEFAULT 1,
  `min_value` int unsigned NOT NULL DEFAULT 1,
