  `sent_on` datetime NOT NULL,
  `status` varchar(32) NOT NULL,
  `gateway_response_code` varchar(64),
  `sender_code` varchar(16) NOT NULL,
  `notification_code` varchar(32),
  `scenario_id` int,
  `stan` varchar(64),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bb_notifications`.`sms_scenario`;
CREATE TABLE `bb_notifications`.`sms_scenario` (
