  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dsa_notifications`.`notification_message`;
CREATE TABLE `dsa_notifications`.`notification_message` (
