  `handle_value` varchar(255),
  `message` varchar(800),
  `subject` varchar(500),
  `sent_on` timestamp,
  `status` varchar(255),
  `code` varchar(255),
  `sender_code` varchar(255),
  `retry_count` int,
  `stan` varchar(255),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dsa_notifications`.`sequences`;
CREATE TABLE `dsa_notifications`.`sequences` (
